import subprocess, re, json, math, sys
from PIL import Image

CHROME = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome"
HTML = "/Users/taha/Documents/portfolio.me/runs/sadeqi-me/prototypes/03-modes.html"
MODE_FLAG = {"dark": 0, "light": 1}

def get_bboxes(mode, width=1440, height=900):
    flag = MODE_FLAG[mode]
    out = subprocess.run([
        CHROME, "--headless", "--disable-gpu", "--hide-scrollbars",
        f"--blink-settings=preferredColorScheme={flag}",
        "--run-all-compositor-stages-before-draw", "--virtual-time-budget=5000",
        f"--window-size={width},{height}", "--dump-dom",
        f"file://{HTML}"
    ], capture_output=True, text=True, timeout=30)
    m = re.search(r'id="aaa-bboxes">\s*(\{.*?\})\s*</script>', out.stdout, re.S)
    if not m:
        raise RuntimeError("bbox script tag not found in dumped DOM")
    return json.loads(m.group(1))

def parse_rgb(s):
    m = re.match(r"rgba?\((\d+),\s*(\d+),\s*(\d+)", s)
    return tuple(int(x) for x in m.groups())

def srgb_to_linear(c):
    c = c/255.0
    return c/12.92 if c <= 0.03928 else ((c+0.055)/1.055)**2.4

def rel_lum(rgb):
    r,g,b = rgb
    return 0.2126*srgb_to_linear(r) + 0.7152*srgb_to_linear(g) + 0.0722*srgb_to_linear(b)

def contrast(rgb1, rgb2):
    L1, L2 = rel_lum(rgb1), rel_lum(rgb2)
    lo, hi = min(L1,L2), max(L1,L2)
    return (hi+0.05)/(lo+0.05)

def dist(p, q):
    return math.sqrt(sum((a-b)**2 for a,b in zip(p,q)))

CORE_THRESH = 20
BG_FRACTION = 0.6
MIN_CORE_PX = 10

def sample(img, box, ink_rgb):
    crop = img.crop(box)
    pixels = list(crop.getdata())
    dists = [dist(p, ink_rgb) for p in pixels]
    max_d = max(dists)
    core = [p for p,d in zip(pixels,dists) if d <= CORE_THRESH]
    bg_thresh = max_d * BG_FRACTION
    bg = [p for p,d in zip(pixels,dists) if d >= bg_thresh]
    if len(core) < MIN_CORE_PX:
        return {"error": f"only {len(core)} core px found (<{MIN_CORE_PX}) — sample unreliable"}
    core_mean = tuple(sum(c[i] for c in core)/len(core) for i in range(3))
    ratios = [contrast(core_mean, b) for b in bg]
    return {
        "core_px": len(core), "bg_px": len(bg), "total_px": len(pixels),
        "core_mean": tuple(round(x,1) for x in core_mean),
        "min_ratio": min(ratios), "median_ratio": sorted(ratios)[len(ratios)//2],
        "max_ratio": max(ratios),
    }

for mode, shot in [("light", "/Users/taha/Documents/portfolio.me/runs/sadeqi-me/shots/prototypes/03-light-1440.png"),
                   ("dark", "/Users/taha/Documents/portfolio.me/runs/sadeqi-me/shots/prototypes/03-dark-1440.png")]:
    print("="*20, mode, "="*20)
    bboxes = get_bboxes(mode)
    img = Image.open(shot).convert("RGB")
    for name, b in bboxes.items():
        if b["disabled"]:
            print(f"{name}: SKIPPED (disabled control, WCAG 1.4.3 exempt)")
            continue
        pad = 2
        box = (max(0,int(b["x"])-pad), max(0,int(b["y"])-pad),
               int(b["x"]+b["w"])+pad, int(b["y"]+b["h"])+pad)
        if box[3] > img.height or box[2] > img.width:
            print(f"{name}: OUT OF FRAME {box} vs img {img.size}")
            continue
        ink = parse_rgb(b["color"])
        res = sample(img, box, ink)
        print(name, "ink(css)=", ink, res)
